3	<template>
4	  <div class="page-container" @swipe="onSwipe">
5	    <!-- 整页纵向滚动：两块各占一屏，滑动停止后自动吸附（类似番茄钟分页）；每屏自带状态栏；搜索态结果随其滚动 -->
6	    <scroll id="pageScroll" class="page-scroll" scroll-y="{{!voiceActive}}" onscroll="onPageScroll" onscrollbottom="onPageScrollBottom">
7	      <!-- 第一块：顶部块。高度由 style 动态提供（screen1H）：非搜索态=整屏高（与第二屏构成
8	           双屏吸附），搜索态=头部高（状态栏+搜索框）让结果区紧跟其后进入 pageScroll 内容流。
9	           ⚠️ 结果列表不能放进固定高容器、也不能包内层 scroll（v1.16.11/v1.16.29 两次教训）：
10	           嵌套 scroll 或 flex:1 失效都会造成「内容溢出不可见 + 手势死区 = 滑不动」。
11	           现在结果区是 pageScroll 的直接子项，随内容自然撑高，单层滚动。 -->
12	      <div class="screen1" style="height: {{screen1H}}px;">
13	        <!-- 状态栏时间 + 应用名（每屏独立渲染，随内容滚动）；搜索态标题切换为 searchTitle -->
14	        <div class="statusbar">
15	          <!-- 矩形手表：左占位 + 顶部居中标题 + 右上时间（三栏 flex 均分保证标题绝对居中） -->
16	          <div class="sb-left" if="{{showRectTitle}}"></div>
17	          <text class="rect-title" if="{{showRectTitle}}">{{headerTitle}}</text>
18	          <div class="sb-block">
19	            <text class="time">{{time}}</text>
20	            <text class="app-title" if="{{showAppTitle}}">{{headerTitle}}</text>
21	          </div>
22	        </div>
23	
24	        <!-- 搜索框：常驻顶部；非搜索态点击进入搜索，搜索态点击开/收键盘；有词显示输入内容与 ✕ -->
25	        <div class="search-box {{searchBoxClass}}" @click="toggleSearchBox">
26	          <image class="search-box-icon" src="/common/icons/search.png" if="{{!searchQuery && !voiceActive}}"></image>
27	          <text class="search-placeholder" if="{{searchActive && !searchQuery && !voiceActive}}">请输入</text>
28	          <text class="search-input" if="{{searchActive && searchQuery && !voiceActive}}">{{displayQuery}}</text>
29	          <text class="clear-btn" if="{{searchActive && searchQuery && !voiceActive}}" @click="clearSearch">✕</text>
30	          <text class="voice-text" if="{{voiceActive}}">聆听中…</text>
31	        </div>
32	
33	        <!-- 引导词：非搜索态、非语音态显示 -->
34	        <text class="guide" if="{{!searchActive && !voiceActive}}">{{guideText}}</text>
35	
36	        <!-- 分类横滑行：非搜索态、非语音态显示 -->
37	        <scroll id="catScroll" class="cat-scroll" if="{{!searchActive && !voiceActive}}" scroll-x="{{true}}" onscroll="onCatScroll">
38	          <div class="cat-row">
39	            <div class="cat-item" for="{{displayCats}}" @click="goCategory($item)">
40	              <div class="cat-icon {{$item.colorClass}}">
41	                <image class="cat-icon-img" src="{{$item.icon}}"></image>
42	              </div>
43	              <text class="cat-text">{{$item.name}}</text>
44	            </div>
45	          </div>
46	        </scroll>
47	    <!-- 两个搜索按钮：矩形左右排列、胶囊/圆形上下排列；左「语音搜索」、右「AI搜索」 -->
48	        <div class="search-btn-row" if="{{!searchActive && !showKeyboard && !voiceActive}}">
49	          <div class="search-btn search-btn-l" @click="startVoiceSearch">
50	            <image class="search-icon" src="/common/icons/voice.png"></image>
51	            <text if="{{!isCircle}}" class="search-text">语音搜索</text>
52	          </div>
53	          <div class="search-btn search-btn-r" @click="goSearch">
54	            <image class="search-icon" src="/common/icons/ai.png"></image>
55	            <text if="{{!isCircle}}" class="search-text">AI搜索</text>
56	          </div>
57	        </div>
58	
59	        <!-- 语音聆听态：蓝牙未连接显示断开图标+提示，已连接显示波形动画（随音量）；取消按钮 -->
60	        <div class="voice-panel" if="{{voiceActive}}">
61	          <image class="voice-bt-off" src="/common/icons/bluetooth_off.png" if="{{!bluetoothConnected}}"></image>
62	          <text class="voice-tip" if="{{!bluetoothConnected}}">蓝牙未连接</text>
63	          <text class="voice-tip" if="{{bluetoothConnected}}">{{voiceStatusText}}</text>
64	          <div class="voice-cancel" @click="exitVoiceSearch">
65	            <text class="voice-cancel-text">取消</text>
66	          </div>
67	        </div>
68	
69	      </div>
70	
71	      <!-- 搜索结果区（v1.16.37 重构）：pageScroll 的直接子项，随内容自然撑高——
72	           单层滚动（修复「搜完滑不动」），滚到底自动加载下一页（pageScroll 的 onscrollbottom）。
73	           不再使用内层 scroll（v1.16.29 方案在手环轻量运行时 flex:1 失效 → 容器被内容
74	           撑开成手势死区，主人实测「还是滑动不了」）。 -->
75	      <div class="home-result" if="{{searchActive}}">
76	        <!-- AI 回答卡（v1.16.33）：AI 搜索的问题回答；来源条目在其下方的结果列表 -->
77	        <div class="ai-card" if="{{aiMode && (aiThinking || aiAnswer)}}">
78	          <text class="ai-card-title">{{aiCardTitle}}</text>
79	          <text class="ai-card-text">{{aiCardText}}</text>
80	        </div>
81	        <!-- 结果计数：键盘打开也保持显示（v1.16.38）——此前 !showKeyboard 条件让键盘弹出时
82	             这行消失、下方卡片整体上顶一下；流式布局下保留它无任何副作用 -->
83	        <text class="result-count" if="{{searched && !loading && !aiMode}}">共 {{totalCount}} 条结果</text>
84	        <text class="engine-tip" if="{{showEngineTip}}" @click="goSettings">数据未就绪 · 点此去设置检查</text>
85	        <div class="result-item" for="{{visibleList}}" @click="gotoDetail($item.id)">
86	          <!-- 三行类名由 DatasetManager 按 meta.display.card 预拼完整类名（纯变量插值，禁拼接表达式） -->
87	          <text class="{{$item.yearClass}}">{{$item.yearDisplay}}</text>
88	          <text class="{{$item.titleClass}}">{{$item.title}}</text>
89	          <text class="{{$item.catClass}}">{{$item.region}}</text>
90	        </div>
91	        <text class="empty-tip" if="{{searchError && !loading}}">搜索出错 · 请重试</text>
92	        <text class="empty-tip" if="{{searched && displayList.length === 0 && !loading && !searchError}}">无结果</text>
93	        <text class="empty-tip" if="{{!searched && displayList.length === 0}}">{{waitTip}}</text>
94	        <!-- 显示更多（v1.16.26 主人要求：默认只渲染 5 条，点此追加）-->
95	        <div class="more-btn" if="{{displayList.length > visibleCount}}" @click="showMore">
96	          <text class="more-text">{{moreText}}</text>
97	        </div>
98	        <text class="empty-tip" if="{{allLoaded && displayList.length > 0}}">— 已显示全部 —</text>
99	      </div>
100	
101	      <!-- 第二块：状态栏 + 设置 / 收藏（一屏高）；搜索态隐藏（if 不占位） -->
102	      <div class="screen2" if="{{!searchActive}}" style="height: {{screen1H}}px;">
103	        <!-- 状态栏时间 + 应用名（第二屏顶部独立渲染，标题为「选项」） -->
104	        <div class="statusbar">
105	          <div class="sb-block">
106	            <text class="time">{{time}}</text>
107	            <text class="app-title" if="{{showAppTitle}}">{{secondTitle}}</text>
108	          </div>
109	        </div>
110	
111	        <!-- 设置 / 收藏卡片：占满剩余高度并垂直居中 -->
112	        <div class="sec2-wrap">
113	          <div class="sec2">
114	            <div class="sec2-card sec2-card-first" @click="goSettings">
115	              <image class="sec2-icon" src="/common/icons/set.png"></image>
116	              <text class="sec2-text">设置</text>
117	            </div>
118	            <div class="sec2-card" @click="goFavorites">
119	              <image class="sec2-icon" src="/common/icons/star.png"></image>
120	              <text class="sec2-text">{{favoriteText}}</text>
121	            </div>
122	          </div>
123	        </div>
124	      </div>
125	    </scroll>
126	
127	    <!-- 右侧分页指示点：当前页白色、另一页灰色；搜索态隐藏 -->
128	    <div class="page-dots" if="{{!searchActive}}" style="top: {{dotsTop}}px;">
129	      <div class="{{dot0Class}}"></div>
130	      <div class="{{dot1Class}}"></div>
131	    </div>
132	
133	    <!-- 键盘区：absolute 底部；搜索态弹出（rect 组件原生 / circle 外层 scale 0.625 / pill 撑满）。
134	         v1.16.2 修复「键盘能开但按键全无反应」：v1.14.3 曾把 kb-wrap 移入 screen1（pageScroll 内），
135	         其后的 home-result-scroll（常驻 DOM、flex:1 占满搜索框以下整屏、透明背景）在 DOM 顺序上压住键盘，
136	         轻量运行时 z-index 不赢得命中测试 → 键盘可见但全部按键点击被 scroll 吞掉。
137	         现移回 page-container 根层级 + DOM 末尾（v1.13.x / result.ux / historyband9 的已验证位置）：
138	         绘制与命中都优先；几何不变（absolute 的包含块本来就是 page-container） -->
139	    <div class="kb-wrap" show="{{showKeyboard}}">
140	      <div class="kb-body kb-rect" if="{{screentype === 'rect'}}">
141	        <input-method hide="{{!showKeyboard}}" keyboardtype="QWERTY" screentype="rect" maxlength="20" @complete="onInput" @delete="onDelete"></input-method>
142	      </div>
143	      <div class="kb-body kb-circle" if="{{screentype === 'circle'}}">
144	        <input-method hide="{{!showKeyboard}}" keyboardtype="QWERTY" screentype="circle" maxlength="20" @complete="onInput" @delete="onDelete"></input-method>
145	      </div>
146	      <div class="kb-body kb-pill" if="{{screentype === 'pill-shaped'}}">
147	        <input-method hide="{{!showKeyboard}}" keyboardtype="QWERTY" screentype="pill-shaped" maxlength="20" @complete="onInput" @delete="onDelete"></input-method>
148	      </div>
149	    </div>
150	  </div>
151	</template>
