153	<style>
154	  /* ===== 基础样式（矩形 rect，designWidth 300 基准） ===== */
155	  .page-container { position: relative; width: 100%; height: 100%; background-color: #000000; }
156	  .page-scroll { width: 100%; height: 100%; flex-direction: column; }
157	
158	  /* 状态栏：每屏顶部普通块级（随内容滚动）；矩形时间靠右，下方小字应用名；左右对称 padding 保证三栏均分后标题落于屏正中 */
159	  .statusbar { width: 100%; height: 22px; flex-direction: row; justify-content: flex-end; align-items: center; padding-left: 30px; padding-right: 30px; flex-shrink: 0; }
160	  .sb-left { flex: 1; }
161	  .sb-block { flex: 1; flex-direction: column; align-items: flex-end; }
162	  .time { font-size: 16px; color: #757575; font-weight: 400; }
163	  .app-title { font-size: 18px; color: #FFFFFF; font-weight: 500; margin-top: 3px; }
164	  /* 矩形手表：顶部应用名（大小约胶囊 3/4），三栏 flex 均分（sb-left/rect-title/sb-block）保证水平正中心，不干扰右上时间 */
165	  .rect-title { flex: 1; text-align: center; font-size: 20px; color: #FFFFFF; font-weight: 500; }
166	
167	  /* 第一块：高度由模板 style 动态提供（screen1H：非搜索态=整屏高 / 搜索态=头部高），
168	     CSS 不再固定——固定高是「搜完滑不动」的根因（结果溢出固定高容器不可滚） */
169	  .screen1 { width: 100%; flex-direction: column; align-items: center; flex-shrink: 0; }
170	
171	  /* 分类横滑行：图标直径 58、间距 17、名称 13px；边缘留白 8.5（间距=2×边缘） */
172	  .cat-scroll { width: 100%; height: 82px; margin-top: 61px; flex-shrink: 0; }
173	  .cat-row { flex-direction: row; align-items: flex-start; padding-left: 8px; padding-right: 8px; }
174	
175	  .cat-item { width: 58px; flex-direction: column; align-items: center; margin-right: 17px; flex-shrink: 0; }
176	  .cat-icon { width: 58px; height: 58px; border-radius: 29px; background-color: #1C1C1E; justify-content: center; align-items: center; }
177	  /* Google/Material 鲜活配色图标底（语义化：健康绿/科学蓝/历史橙/生活青/急救红/运动黄） */
178	  .ci-green { background-color: #34A853; }
179	  .ci-blue { background-color: #4285F4; }
180	  .ci-orange { background-color: #FB8C00; }
181	  .ci-cyan { background-color: #24C1E0; }
182	  .ci-red { background-color: #EA4335; }
183	  .ci-yellow { background-color: #FBBC05; }
184	  .ci-ds { background-color: #8B5CF6; }
185	  .cat-icon-img { width: 33px; height: 33px; }
186	  .cat-text { font-size: 13px; color: #e6edf3; margin-top: 6px; }
187	
188	  /* 引导词：灰色小字居中（位于分类图标上方，紧贴搜索框下方） */
189	  .guide { width: 100%; text-align: center; font-size: 13px; color: #5b6472; letter-spacing: 2px; margin-top: 12px; flex-shrink: 0; }
190	
191	  /* 搜索框：位于状态栏下方，深色圆角输入框样式，放大镜靠左，带描边，点击进入搜索页 */
192	  .search-box { width: 258px; height: 56px; border-radius: 28px; background-color: #1C1C1E; border: 2px solid #3A3A3C; flex-direction: row; justify-content: flex-start; align-items: center; padding-left: 18px; margin-top: 16px; flex-shrink: 0; }
193	  .search-box-icon { width: 24px; height: 24px; }
194	  .voice-text { font-size: 20px; color: #757575; flex: 1; margin-left: 10px; text-align: left; }
195	
196	  /* 搜索按钮行：矩形左右排列，胶囊/圆形上下排列 */
197	  .search-btn-row { width: 100%; flex-direction: row; justify-content: center; align-items: center; margin-top: 20px; padding-left: 10px; padding-right: 10px; flex-shrink: 0; }
198	  .search-btn { position: relative; flex: 1; height: 67px; border-radius: 33px; background-color: #4D9FEE; flex-direction: row; justify-content: flex-start; align-items: center; flex-shrink: 0; padding-left: 14px; }
199	  .search-btn-l { margin-right: 4px; background-color: #34A853; }
200	  .search-btn-r { margin-left: 4px; background-color: #2A2A2C; }
201	  .search-icon { width: 21px; height: 21px; margin-right: 5px; flex-shrink: 0; }
202	  .voice-panel { width: 100%; flex: 1; flex-direction: column; justify-content: center; align-items: center; }
203	  .voice-tip { font-size: 24px; color: #FFFFFF; margin-bottom: 12px; }
204	  .voice-bt-off { width: 50px; height: 50px; margin-bottom: 12px; }
205	  .voice-cancel { width: 160px; height: 56px; border-radius: 28px; background-color: #3A3A3C; justify-content: center; align-items: center; margin-top: 30px; }
206	  .voice-cancel-text { font-size: 24px; color: #FFFFFF; }
207	  .search-text { font-size: 22px; color: #FFFFFF; font-weight: 400; }
208	
209	  /* 第二块：状态栏固定高度在顶部，剩余空间由 sec2-wrap 撑起并让卡片垂直居中 */
210	  .screen2 { width: 100%; flex-direction: column; align-items: center; flex-shrink: 0; }
211	  .sec2-wrap { width: 100%; flex: 1; justify-content: center; align-items: center; }
212	  .sec2 { width: 100%; flex-direction: row; padding-left: 21px; padding-right: 21px; flex-shrink: 0; }
213	  .sec2-card { flex: 1; height: 150px; border-radius: 21px; background-color: #1C1C1E; flex-direction: column; justify-content: center; align-items: center; }
214	  .sec2-card-first { margin-right: 14px; }
215	  .sec2-icon { width: 36px; height: 36px; }
216	  .sec2-text { font-size: 17px; color: #FFFFFF; font-weight: 600; margin-top: 12px; }
217	
218	  /* 分页指示点：右边缘竖排两个小圆点 */
219	  .page-dots { position: absolute; right: 4px; flex-direction: column; align-items: center; z-index: 10; }
220	  .page-dot { width: 10px; height: 10px; border-radius: 5px; margin-bottom: 12px; background-color: #4a4a4a; }
221	  .page-dot-active { background-color: #FFFFFF; }
222	
223	  /* ===== 主页内嵌搜索（搜索态结果区替换分类行，随外层 pageScroll 滚动） ===== */
224	  /* 结果区独立滚动容器（v1.16.29）：占满 screen1（CSS 固定一屏高）剩余空间。
225	     ⚠️ 此前 flex:1 与 flex-shrink:0 并存互相冲突——flex-shrink:0 使容器被内容撑开、
226	     永远成不了滚动视图，结果超出后既不可见也滑不动（主人反馈「搜完滑不动」）。 */
227	  .home-result { width: 100%; flex-direction: column; align-items: center; flex-shrink: 0; }
228	
229	  /* 搜索框内占位/输入/清空三件套（复用主页 .search-box 同名义尺寸；无独立 search-wrap 包裹） */
230	  .search-placeholder { font-size: 20px; color: #757575; flex: 1; margin-left: 10px; text-align: left; }
231	  .search-input { font-size: 22px; color: #FFFFFF; flex: 1; margin-left: 10px; text-align: left; }
232	  .clear-btn { width: 28px; height: 28px; border-radius: 14px; background-color: #3A3A3C; color: #FFFFFF; text-align: center; font-size: 18px; line-height: 28px; margin-right: 14px; flex-shrink: 0; }
233	
234	  .result-count { width: 100%; text-align: center; font-size: 16px; color: #757575; margin-top: 6px; flex-shrink: 0; }
235	
236	  /* 引擎未加载提示：黄色醒目，点击跳设置 */
237	  .engine-tip { width: 100%; text-align: center; font-size: 18px; color: #FBBC05; margin-top: 8px; flex-shrink: 0; }
238	
239	  /* 结果列表（搜索结果随外层 pageScroll 流式滚动，无需内嵌 scroll） */
240	  .result-item { width: 94%; margin-left: 3%; border-radius: 14px; background-color: #1C1C1E; padding: 10px 14px; margin-bottom: 6px; flex-direction: column; flex-shrink: 0; }
241	  /* 「显示更多」按钮（v1.16.26）*/
242	  /* AI 回答卡（v1.16.33）：区别于普通结果卡的强调样式 */
243	  .ai-card { width: 94%; margin-left: 3%; border-radius: 14px; background-color: #1C2530; border: 1px solid #2A4A66; padding: 12px 14px; margin-bottom: 8px; flex-direction: column; flex-shrink: 0; }
244	  .ai-card-title { font-size: 18px; color: #4D9FEE; font-weight: 600; margin-bottom: 6px; }
245	  .ai-card-text { font-size: 18px; color: #E8E8E8; line-height: 26px; }
246	  .more-btn { width: 94%; margin-left: 3%; height: 64px; border-radius: 14px; background-color: #2C2C2E; justify-content: center; align-items: center; margin-top: 4px; margin-bottom: 8px; flex-shrink: 0; }
247	  .more-text { font-size: 22px; color: #4D9FEE; }
248	  .result-year { font-size: 20px; font-weight: bold; color: #4D9FEE; margin-bottom: 2px; }
249	  .result-title { font-size: 22px; color: #FFFFFF; margin-bottom: 1px; }
250	  .result-region { font-size: 17px; color: #757575; }
251	  /* 结果卡三行大小（meta.display.card.rows → DatasetManager 预拼 sz-* 类 → 模板纯变量插值）。
252	     仅声明了 display.card 的集（英语集）会带 sz 类；未声明的集（历史/诗词）保持上方基准字号。
253	     注意：sz 规则需在每个形态块内重复声明且位于 .result-* 之后，否则会被形态基准覆盖 */
254	  .sz-large { font-size: 30px; }
255	  .sz-medium { font-size: 22px; }
256	  .sz-small { font-size: 16px; }
257	
258	  .empty-tip { width: 100%; text-align: center; font-size: 18px; color: #757575; margin-top: 40px; }
259	
260	  /* 键盘区：absolute 底部；rect 用原组件（255px 满宽）、circle 画布 480px 整体 scale 0.625、
261	     pill 组件内部已按 300 基准重写，此处直接撑满（与 result.ux 同款） */
262	  .kb-wrap { position: absolute; left: 0; bottom: 0; width: 100%; overflow: visible; z-index: 20; }
263	  .kb-rect { position: relative; width: 100%; height: 255px; }
264	  .kb-circle { position: relative; left: -90px; width: 480px; height: 321px; transform: scale(0.625); transform-origin: 240px 321px; }
